import { DeltaBars, type DeltaSeries } from "@/components/vizcn/delta-bars"

/**
 * Demo: daily request volume for two rival models over 30 days.
 * Deterministic synthetic waves: Atlas trends up and takes the lead
 * mid-month; one reporting gap (null on both) shows the missing-day hole.
 */

const N = 30

function wave(i: number, base: number, trend: number, amp: number, phase: number): number {
  return Math.round(
    base + i * trend + amp * Math.sin(i / 3.1 + phase) + amp * 0.5 * Math.sin(i / 1.6 + phase * 2)
  )
}

const ATLAS: DeltaSeries = {
  label: 'Atlas',
  values: Array.from({ length: N }, (_, i) => (i === 17 ? null : wave(i, 480_000, 9_500, 90_000, 0.4))),
}

const NOVA: DeltaSeries = {
  label: 'Nova',
  values: Array.from({ length: N }, (_, i) => (i === 17 ? null : wave(i, 590_000, 1_500, 80_000, 2.3))),
}

const X_LABELS = [
  { frac: 0.02, text: 'Jun 1' },
  { frac: 0.34, text: 'Jun 11' },
  { frac: 0.67, text: 'Jun 21' },
  { frac: 0.98, text: 'Jun 30' },
]

export default function DeltaBarsDemo() {
  return (
    <div className="mx-auto max-w-4xl p-6">
      <DeltaBars a={ATLAS} b={NOVA} xLabels={X_LABELS} />
    </div>
  )
}

'use client'

import { RAMP } from '../../lib/palette'
import { DuneAreaChart } from "@/components/vizcn/dune-flow"

/**
 * Demo: open evaluation tasks by priority over six weeks — an ORDINAL
 * series (Low → Medium → High), so it uses the single-hue RAMP instead of
 * categorical hues. Data is deterministic (smooth waves, no randomness).
 */

const N = 42
const START = Date.UTC(2026, 0, 5) // 2026-01-05
const DAY_MS = 86_400_000

const days = Array.from({ length: N }, (_, i) =>
  new Date(START + i * DAY_MS).toISOString().slice(0, 10)
)

const wave = (i: number, base: number, amp: number, period: number, phase: number) =>
  Math.round(base + amp * Math.sin((i / period) * Math.PI * 2 + phase) + (amp / 3) * Math.sin(i / 2.7 + phase))

const low = Array.from({ length: N }, (_, i) => wave(i, 34, 12, 21, 0.4))
const medium = Array.from({ length: N }, (_, i) => wave(i, 22, 9, 17, 2.1))
const high = Array.from({ length: N }, (_, i) => Math.max(0, wave(i, 10, 8, 14, 4.2)))

export default function DuneFlowDemo() {
  return (
    <DuneAreaChart
      days={days}
      series={[
        { label: 'Low', color: RAMP[0], values: low },
        { label: 'Medium', color: RAMP[1], values: medium },
        { label: 'High', color: RAMP[2], values: high },
      ]}
      yLabel="Open evaluation tasks by priority"
    />
  )
}

